  const categories = [['all', 'For You'], ['verified', 'Onchain'], ['perps', 'Perps'], ['prediction', 'Prediction Markets'], ['opinions', 'Opinions'], ['trends', 'Trends'], ['spots', 'Spots'], ['trenches', 'Trenches']];
  const savedSet = key => new Set(JSON.parse(localStorage.getItem(key) || '[]'));
  const saveSet = (key, values) => localStorage.setItem(key, JSON.stringify([...values]));
