    const prediction = `<div class="coming-panel prediction-partner"><div class="partner-top"><div class="coming-icon">L</div><div><span class="coming-label">SELECTED INTEGRATION TARGET</span><h2>Prediction markets through Levr Bet</h2></div></div><p>Levr Bet runs leveraged event markets on Monad. Stance will surface its real markets here when partner market data and trading access are approved.</p><div class="blocker"><span>COMING SOON</span><p>The protocol is live, but a public embeddable trading API or supported partner contract interface is not currently documented. Stance will not imitate the market with internal demo data.</p></div><div class="partner-actions"><a class="primary" href="https://levr.bet" target="_blank" rel="noreferrer">Open Levr Bet ↗</a><button class="secondary" data-route="markets">Open Stance Market</button></div></div>`;
    const perps = `<div class="coming-panel"><div class="coming-icon">↗</div><span class="coming-label">COMING SOON</span><h2>Perpetual positions through Perpl</h2><p>Open long or short positions with leverage, attach the trade to a Stance, and follow entry, liquidation, and exit activity.</p><div class="blocker"><span>WHY IT IS NOT LIVE</span><p>Perpl public Monad data is connected. Account and order access still requires Perpl to authorize the Stance production origin.</p></div><button class="secondary" data-route="integrations">View integration status</button></div>`;
    const next = `<section class="trade-next" id="trade-next" hidden><div><p class="eyebrow">TRADE CONFIRMED</p><h2>What should this trade become?</h2><p>A transaction can become a public Stance, connect to an existing Stance, or sit inside a public Portfolio.</p></div><div class="next-actions"><button class="next-card live" data-post-trade="publish"><span>01 · LIVE</span><b>Publish a new Stance</b><small>Write the thesis and use this transaction as its onchain evidence.</small></button><button class="next-card" disabled><span>02 · COMING SOON</span><b>Attach to an existing Stance</b><small>Requires an onchain amendment link without changing the original record.</small></button><button class="next-card" disabled><span>03 · COMING SOON</span><b>Add to a public Portfolio</b><small>Requires public Portfolio grouping in the next contract release.</small></button></div></section>`;
